prompt:
The library function `ledger::add_small` returns how many transfers succeeded but its contract does not bound that number. Add to its postcondition that the result is at most a.len(), keeping everything else.

Required signature (in unit `ledger`):
fn add_small(a: &mut [i64], from: usize, x: i64) -> (r: usize)

reference.code:
spec fn paid_ok(a: &[i64], r: usize) -> bool { r <= a.len() }

#[effects(pure)]
#[uses(amount_ok, debited, in_closed, paid_ok)]
fn add_small(a: &mut [i64], from: usize, x: i64) -> (r: usize)
    requires amount_ok(a), debited(a, from), in_closed(x),
    ensures amount_ok(a), paid_ok(a, r),
{
    let mut paid: usize = 0;
    let mut k: usize = 0;
    while k < a.len()
        invariant k <= a.len(), paid <= k, from < a.len(), amount_ok(a),
        decreases a.len() - k,
    {
        if balance(a, from, k, x) {
            paid = paid + 1;
        }
        k = k + 1;
    }
    paid
}
